import { Table, ReferenceColumn, ConditionsColumn, StringColumn, GenericColumn } from '@servicenow/sdk/core'

export const email_access_restriction = Table({
    allowWebServiceAccess: true,
    audit: true,
    display: 'notification',
    extends: 'sys_metadata',
    label: 'Email Access Restriction',
    name: 'email_access_restriction',
    schema: {
        notification: ReferenceColumn({
            label: 'Notification',
            referenceTable: 'sysevent_email_action',
        }),
        conditions: ConditionsColumn({
            dynamicValueDefinitions: {
                type: 'dependent_field',
                columnName: 'notification.collection',
            },
            label: [
                {
                    hint: "Read access to an email record is granted when conditions evaluate to true against an email's target record",
                    label: 'Conditions',
                    plural: 'Conditions',
                    language: 'en',
                },
            ],
            maxLength: 8000,
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 1000,
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
    },
    textIndex: true,
})
